import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import Popup from "./Popup";
import axios from "axios";
import { Group } from "../Model/Group.model";
import "./styles/Groups.scss";
import GroupNavBar from "./GroupNavBar";
import { APIService } from "../api/requests";
import {
  Button,
  Checkbox,
  Container,
  createTheme,
  Flex,
  MantineProvider,
  Paper,
} from "@mantine/core";
import { IconTrash, IconUsersGroup } from "@tabler/icons-react";
import { group } from "console";

function Groups() {
  const navigate = useNavigate();
  const [groups, setGroups] = useState<Group[]>([]);
  const [showPopup, setShowPopup] = useState<boolean>(false);
  const [showDelete, setShowDelete] = useState(false);
  const [showDeleteAll, setDeleteAll] = useState(false);
  let [selectedItems, setCount] = useState(0);

  const theme = createTheme({
    cursorType: "pointer",
  });

  useEffect(() => {
    setCount(0);
    axios
      .get<Group[]>(`http://localhost:5257/api/Group/`)
      .then((response) => {
        setGroups(response.data);
        console.log(response.data);
      })
      .catch((error) => {
        console.log(error);
      });
  }, []);

  const openGroup = (event: any, groupId: string) => {
    event?.stopPropagation();
    navigate(`/group/${groupId}`);
  };
  const handleOpenPopup = () => {
    setShowPopup(true);
  };

  const handleClosePopup = () => {
    setShowPopup(false);
  };

  const handleSelection = (isChecked: boolean, Id: string) => {
    // setShowDelete(isChecked);
    // if (isChecked) {
    //   setCount(++selectedItems);
    // } else {
    //   setCount(--selectedItems);
    // }

  };

  const onCreate = (value: string) => {
    // axios
    //   .post<Group>("http://localhost:5257/api/Group", { name: value })
    //   .then((response) => {
    //     setGroups((old) => [...old, response.data]);
    //   })
    //   .catch((error) => {
    //     alert("Name cannot be empty");
    //   });
    APIService.group.postGroup({ name: value }).then((response) => {
      setGroups((old) => [...old, response.data]);
    });
  };

  const checkHandler = (idToUpdate: string, checked: boolean) => {
    const group = groups.find((x) => x.id === idToUpdate);
    if (group != null) {
      setGroups((group) =>
        group.map((x) =>
          x.id === idToUpdate ? { ...x, isChecked: !checked } : x
        )
      );
    }
  };
  return (
    <>
      <Paper shadow="xs">
        <GroupNavBar />
      </Paper>
      <Container size="lg" w="90%">
        <Flex
          bg="white"
          justify="space-between"
          align="center"
          pt="xs"
          pb="xs"
          p="sm"
          style={{ borderTopLeftRadius: "20px", borderTopRightRadius: "20px" }}
          mt="md"
        >
          <MantineProvider theme={theme}>
            <Checkbox
              size="sm"
              me="sm"
              label="Select All"
              onChange={() => setDeleteAll(!showDeleteAll)}
            ></Checkbox>
          </MantineProvider>

          <Button
            color="red"
            radius="20px"
            className={selectedItems > 0 ? "button show" : "button"}
          >
            <IconTrash size="20" className="me-1" />
            Delete Selected
          </Button>
        </Flex>
        {/* Group section */}
        {groups.map((group) => (
          <Flex align="flex-start" bg="white" p="sm" className="shadow">
            <MantineProvider theme={theme}>
              <Checkbox
                size="sm"
                me="sm"
                onChange={(e) => handleSelection(e.target.checked)}
              ></Checkbox>
            </MantineProvider>
            <IconUsersGroup className="me-3" />
            <Flex direction="column" justify="space-between">
              <div className="d-flex fw-semibold">{group.name}</div>
              <div className="small text-muted">
                24 members •<span className="text-danger">Owe: {group.totalOwe}</span> •
                <span className="text-success">Owed: {group.totalOwed}</span> • Created on
              </div>
            </Flex>

            <div className="d-flex align-items-end justify-content-end ms-auto p-2"></div>
          </Flex>
        ))}
      </Container>
    </>
  );
}

export default Groups;
